    insert into public.tools (nombre, protocolo, descripcion) values ($q$NFS$q$, $q$NFS (111/2049 tcp)$q$, $q$Network File System. Permite montar y acceder a sistemas de archivos por red como si fueran locales, tipico de entornos Linux y Unix. Corre sobre el portmapper (111) y el propio servicio (2049). En enumeracion buscamos que shares (exports) estan disponibles, los montamos y revisamos su contenido y permisos.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -p111,2049 10.10.10.10$q$, $q$Escaneo de version sobre los puertos del portmapper y NFS.$q$),
    (t_id, $q$nmap -sV --script nfs* 10.10.10.10 -p111,2049$q$, $q$Corre todos los scripts NSE de NFS, que listan exports, permisos y estadisticas.$q$),
    (t_id, $q$showmount -e 10.10.10.10$q$, $q$Muestra la lista de exports (shares NFS) disponibles en el servidor y quien puede montarlos.$q$),
    (t_id, $q$mkdir target-NFS$q$, $q$Crea un directorio local que servira como punto de montaje para el share NFS.$q$),
    (t_id, $q$mount -t nfs 10.10.10.10:/<share> ./target-NFS/ -o nolock$q$, $q$Monta el export NFS del servidor en el directorio local. -o nolock evita problemas de bloqueo de archivos.$q$),
    (t_id, $q$sudo mount -t nfs 10.10.10.10:/<share> ./target-NFS/ -o nolock$q$, $q$Monta el export NFS con privilegios, necesario en la mayoria de los sistemas.$q$),
    (t_id, $q$ls -la ./target-NFS/$q$, $q$Lista el contenido del share ya montado, con permisos y archivos ocultos.$q$),
    (t_id, $q$umount ./target-NFS$q$, $q$Desmonta el share NFS del directorio local cuando terminas.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres ver que exports (shares NFS) tiene disponibles el servidor 10.10.10.10 antes de montar nada. Escribe el comando.$q$, array[$q$showmount -e 10.10.10.10$q$]::text[], $q$El comando es showmount con el flag -e de exports.$q$, $q$showmount -e 10.10.10.10 lista los exports del servidor NFS y desde que hosts se permite montarlos. Es el primer paso, porque te dice que shares existen y a cuales podrias tener acceso antes de intentar el montaje.$q$),
    (t_id, $q$En 10.10.10.10 encontraste un export llamado /var/nfs y quieres montarlo en un directorio local llamado target-NFS, evitando bloqueos de archivos. Escribe el comando de montaje.$q$, array[$q$sudo mount -t nfs 10.10.10.10:/var/nfs ./target-NFS/ -o nolock$q$, $q$mount -t nfs 10.10.10.10:/var/nfs ./target-NFS/ -o nolock$q$, $q$sudo mount -t nfs 10.10.10.10:/var/nfs ./target-NFS -o nolock$q$, $q$mount -t nfs 10.10.10.10:/var/nfs ./target-NFS -o nolock$q$]::text[], $q$Es mount con -t nfs, la ruta del share como IP:/ruta, el punto de montaje local y el flag -o nolock.$q$, $q$mount -t nfs 10.10.10.10:/var/nfs ./target-NFS/ -o nolock monta el export en tu directorio local. -t nfs indica el tipo de sistema de archivos y -o nolock evita que el cliente intente bloqueos que suelen fallar en labs. Normalmente necesitas sudo. Antes de montar hay que crear el directorio con mkdir.$q$),
    (t_id, $q$Ya montaste el share NFS en ./target-NFS y quieres ver todo su contenido incluyendo archivos ocultos y permisos. Escribe el comando.$q$, array[$q$ls -la ./target-NFS/$q$, $q$ls -la ./target-NFS$q$, $q$ls -la target-NFS/$q$, $q$ls -la target-NFS$q$]::text[], $q$Es un ls -la apuntando al directorio donde montaste el share.$q$, $q$ls -la ./target-NFS/ lista el contenido del share ya montado. Ver los permisos importa en NFS porque a veces los archivos pertenecen a UIDs especificos y puedes necesitar coincidir con ese UID para leerlos, lo que abre trucos de escalada mas adelante.$q$),
    (t_id, $q$Terminaste de revisar el share y quieres desmontarlo del directorio local. Escribe el comando.$q$, array[$q$umount ./target-NFS$q$, $q$sudo umount ./target-NFS$q$, $q$umount target-NFS$q$, $q$sudo umount target-NFS$q$]::text[], $q$El comando para desmontar es umount, sin la n despues de la u.$q$, $q$umount ./target-NFS libera el punto de montaje. Ojo con el nombre del comando, es umount y no unmount, es un error clasico. Conviene desmontar al terminar para dejar limpio el sistema.$q$),
    (t_id, $q$Quieres correr todos los scripts NSE de NFS de nmap contra 10.10.10.10, sobre los puertos del portmapper y el servicio. Escribe el comando.$q$, array[$q$nmap -sV --script nfs* 10.10.10.10 -p111,2049$q$, $q$nmap --script nfs* -sV -p111,2049 10.10.10.10$q$, $q$nmap -sV --script nfs* -p111,2049 10.10.10.10$q$, $q$nmap -p111,2049 --script nfs* -sV 10.10.10.10$q$]::text[], $q$Usa --script con el comodin nfs* y limita a los puertos 111 y 2049.$q$, $q$nmap -sV --script nfs* 10.10.10.10 -p111,2049 corre todos los scripts de NFS (nfs-ls, nfs-showmount, nfs-statfs). Te da los exports y a veces lista el contenido directamente sin necesidad de montar, util para un vistazo rapido.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$DNS$q$, $q$DNS (53 udp/tcp)$q$, $q$Domain Name System. Traduce nombres de dominio a direcciones IP y guarda distintos tipos de registros (A, NS, MX, TXT, SOA). En enumeracion nos interesa consultar registros, identificar la version del servidor y, sobre todo, intentar una transferencia de zona (AXFR), que si esta mal configurada nos entrega el mapa completo de la infraestructura interna. Herramienta principal: dig.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$dig ns <dominio> @10.10.10.10$q$, $q$Consulta los registros NS (nameservers) del dominio contra un servidor DNS especifico.$q$),
    (t_id, $q$dig any <dominio> @10.10.10.10$q$, $q$Pide todos los registros disponibles del dominio en una sola consulta.$q$),
    (t_id, $q$dig soa <dominio> @10.10.10.10$q$, $q$Consulta el registro SOA (Start of Authority), que da datos del servidor autoritativo y los tiempos de la zona.$q$),
    (t_id, $q$dig CH TXT version.bind @10.10.10.10$q$, $q$Consulta la version del servidor DNS usando la clase CHAOS. Puede revelar el software y version de BIND.$q$),
    (t_id, $q$dig axfr <dominio> @10.10.10.10$q$, $q$Intenta una transferencia de zona completa (AXFR). Si el servidor la permite, devuelve todos los registros de la zona.$q$),
    (t_id, $q$dig axfr internal.<dominio> @10.10.10.10$q$, $q$Intenta la transferencia de zona sobre un subdominio interno, que a veces esta permitida aunque la del dominio principal no.$q$),
    (t_id, $q$dnsenum --dnsserver 10.10.10.10 --enum -p 0 -s 0 -o found.txt -f <wordlist> <dominio>$q$, $q$Fuerza por diccionario subdominios del objetivo apoyandose en un wordlist y guarda los encontrados.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres consultar los nameservers (registros NS) del dominio inlanefreight.htb contra el servidor DNS 10.10.10.10. Escribe el comando.$q$, array[$q$dig ns inlanefreight.htb @10.10.10.10$q$, $q$dig NS inlanefreight.htb @10.10.10.10$q$]::text[], $q$Es dig, el tipo de registro ns, el dominio, y el servidor precedido por arroba.$q$, $q$dig ns inlanefreight.htb @10.10.10.10 pregunta cuales son los nameservers del dominio al servidor indicado con @. Saber los NS es util porque son los servidores autoritativos, justo contra los que vas a intentar la transferencia de zona.$q$),
    (t_id, $q$El paso clave de la enumeracion DNS: intenta una transferencia de zona completa del dominio inlanefreight.htb contra el servidor DNS 10.10.10.10. Escribe el comando.$q$, array[$q$dig axfr inlanefreight.htb @10.10.10.10$q$, $q$dig AXFR inlanefreight.htb @10.10.10.10$q$]::text[], $q$El tipo de consulta para transferencia de zona es axfr.$q$, $q$dig axfr inlanefreight.htb @10.10.10.10 pide la zona completa. AXFR significa Asynchronous Full Transfer Zone. Si el servidor esta mal configurado con allow-transfer any, te devuelve todos los registros: subdominios internos, IPs, hosts. Es una de las fugas de informacion mas jugosas del modulo y casi siempre cae en el examen.$q$),
    (t_id, $q$La transferencia de zona del dominio principal fallo, pero quieres probarla sobre el subdominio interno internal.inlanefreight.htb contra el servidor DNS 10.10.10.10. Escribe el comando.$q$, array[$q$dig axfr internal.inlanefreight.htb @10.10.10.10$q$, $q$dig AXFR internal.inlanefreight.htb @10.10.10.10$q$]::text[], $q$Mismo comando de transferencia de zona, pero con el subdominio interno en vez del dominio raiz.$q$, $q$dig axfr internal.inlanefreight.htb @10.10.10.10 prueba la transferencia sobre el subdominio interno. En varios labs la zona del dominio principal esta protegida pero la interna no, asi que cuando el AXFR del dominio raiz falla, siempre vale intentar con los subdominios que hayas descubierto.$q$),
    (t_id, $q$Quieres averiguar la version del servidor DNS 10.10.10.10 usando una consulta TXT de la clase CHAOS a version.bind. Escribe el comando.$q$, array[$q$dig CH TXT version.bind @10.10.10.10$q$, $q$dig ch txt version.bind @10.10.10.10$q$]::text[], $q$Necesitas la clase CH (CHAOS), el tipo TXT y el nombre especial version.bind.$q$, $q$dig CH TXT version.bind @10.10.10.10 consulta la version del servidor usando la clase CHAOS, una clase especial distinta de la comun (IN). Muchos servidores BIND responden con su version exacta, lo que te ayuda a buscar vulnerabilidades conocidas de esa version.$q$),
    (t_id, $q$Quieres pedir todos los registros disponibles del dominio inlanefreight.htb al servidor DNS 10.10.10.10 en una sola consulta. Escribe el comando.$q$, array[$q$dig any inlanefreight.htb @10.10.10.10$q$, $q$dig ANY inlanefreight.htb @10.10.10.10$q$]::text[], $q$El tipo de registro que pide todos a la vez es any.$q$, $q$dig any inlanefreight.htb @10.10.10.10 solicita todos los tipos de registro de una. Aunque muchos servidores modernos limitan la respuesta a ANY, sigue siendo una consulta rapida para ver A, MX, NS y TXT juntos sin lanzar varias consultas separadas.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$SNMP$q$, $q$SNMP (161 udp)$q$, $q$Simple Network Management Protocol. Usado para monitorear y administrar dispositivos de red. Corre sobre UDP 161. La clave del acceso es la community string, que en las versiones 1 y 2c funciona como una contrasena en texto plano. En enumeracion primero descubrimos la community string valida y luego consultamos los OIDs para sacar informacion del sistema: usuarios, procesos, correos de admin, scripts y mas. Herramientas: snmpwalk, onesixtyone y braa.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sU -p161 10.10.10.10$q$, $q$Escaneo del puerto 161 sobre UDP para confirmar que el servicio SNMP esta activo.$q$),
    (t_id, $q$snmpwalk -v2c -c <community_string> 10.10.10.10$q$, $q$Recorre todos los OIDs del dispositivo usando SNMP version 2c y la community string indicada. Vuelca toda la informacion accesible.$q$),
    (t_id, $q$snmpwalk -v2c -c <community_string> 10.10.10.10 <OID>$q$, $q$Consulta un OID especifico en vez de recorrer todo el arbol.$q$),
    (t_id, $q$onesixtyone -c community.txt 10.10.10.10$q$, $q$Fuerza por diccionario la community string del servicio SNMP usando una lista de posibles nombres.$q$),
    (t_id, $q$braa <community_string>@10.10.10.10:.1.3.6.*$q$, $q$Enumera OIDs de forma masiva y rapida una vez que ya tienes la community string valida.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Todavia no conoces la community string del SNMP de 10.10.10.10 y quieres descubrirla por fuerza bruta con onesixtyone usando el wordlist community.txt. Escribe el comando.$q$, array[$q$onesixtyone -c community.txt 10.10.10.10$q$]::text[], $q$onesixtyone usa el flag -c para pasar el archivo de community strings.$q$, $q$onesixtyone -c community.txt 10.10.10.10 prueba muchos nombres de community string a gran velocidad. Como las community strings las nombra el administrador de forma arbitraria (backup, public, private, secret), hay que descubrirlas por diccionario. Sin la community string valida no puedes consultar nada por snmpwalk, por eso este es el primer paso.$q$),
    (t_id, $q$Descubriste que la community string valida de 10.10.10.10 es 'backup'. Recorre todos los OIDs del dispositivo usando SNMP version 2c con snmpwalk. Escribe el comando.$q$, array[$q$snmpwalk -v2c -c backup 10.10.10.10$q$, $q$snmpwalk -c backup -v2c 10.10.10.10$q$]::text[], $q$snmpwalk necesita la version con -v2c y la community string con -c, seguido del objetivo.$q$, $q$snmpwalk -v2c -c backup 10.10.10.10 recorre todo el arbol de OIDs usando la community string 'backup' sobre SNMPv2c. Aqui es donde sale el oro: version del OS, hostname, correo del admin, procesos corriendo, scripts custom y parametros de red. Es la consulta central de la enumeracion SNMP.$q$),
    (t_id, $q$Ya tienes la community string 'backup' de 10.10.10.10 y quieres enumerar OIDs de forma masiva y rapida con braa. Escribe el comando.$q$, array[$q$braa backup@10.10.10.10:.1.3.6.*$q$, $q$braa backup@10.10.10.10:.1.*$q$]::text[], $q$braa usa el formato community@IP:OID, con un comodin al final del OID.$q$, $q$braa backup@10.10.10.10:.1.3.6.* consulta OIDs de forma masiva y mucho mas rapida que snmpwalk, porque implementa su propio stack SNMP y consulta en paralelo. Se usa cuando snmpwalk es lento o cuando quieres barrer un rango grande de OIDs de una vez.$q$),
    (t_id, $q$Quieres confirmar que el servicio SNMP de 10.10.10.10 esta activo escaneando su puerto, recordando que SNMP corre sobre UDP. Escribe el comando de nmap.$q$, array[$q$nmap -sU -p161 10.10.10.10$q$, $q$sudo nmap -sU -p161 10.10.10.10$q$, $q$nmap -p161 -sU 10.10.10.10$q$]::text[], $q$SNMP no es TCP, tienes que usar el tipo de escaneo de UDP en nmap.$q$, $q$nmap -sU -p161 10.10.10.10 escanea el puerto 161 sobre UDP. El detalle clave es -sU, porque SNMP usa UDP y un escaneo TCP normal no lo detectaria. Confirmar que el puerto esta abierto es el arranque antes de buscar la community string.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$MySQL$q$, $q$MySQL (3306 tcp)$q$, $q$Sistema de gestion de bases de datos relacional de codigo abierto, muy comun en stacks LAMP y LEMP. Corre por defecto en el puerto 3306. En enumeracion buscamos la version, credenciales debiles o por defecto, y una vez dentro exploramos bases de datos, tablas y datos sensibles como credenciales, correos y hashes. Cliente principal: mysql.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -sC -p3306 10.10.10.10$q$, $q$Escaneo de version y scripts por defecto sobre el puerto de MySQL.$q$),
    (t_id, $q$nmap -sV -p3306 --script mysql* 10.10.10.10$q$, $q$Corre todos los scripts NSE de MySQL: version, usuarios, bases de datos y chequeo de password vacio.$q$),
    (t_id, $q$nmap -sV -p3306 --script mysql-empty-password 10.10.10.10$q$, $q$Comprueba especificamente si alguna cuenta permite login sin contrasena.$q$),
    (t_id, $q$mysql -u <usuario> -p<contrasena> -h 10.10.10.10$q$, $q$Se conecta al servidor MySQL con usuario y contrasena. Ojo: no hay espacio entre -p y la contrasena.$q$),
    (t_id, $q$mysql -u root -h 10.10.10.10$q$, $q$Intenta conectar como root sin contrasena. Si el servidor lo permite, entra directo.$q$),
    (t_id, $q$show databases;$q$, $q$Dentro de la sesion MySQL, lista todas las bases de datos disponibles.$q$),
    (t_id, $q$use <base_de_datos>;$q$, $q$Dentro de la sesion, selecciona una base de datos para trabajar sobre ella.$q$),
    (t_id, $q$show tables;$q$, $q$Dentro de la base seleccionada, lista todas sus tablas.$q$),
    (t_id, $q$select * from <tabla>;$q$, $q$Dentro de la sesion, muestra todo el contenido de una tabla.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres conectarte al servidor MySQL 10.10.10.10 con el usuario root y la contrasena 'password'. Recuerda el detalle del flag de contrasena. Escribe el comando.$q$, array[$q$mysql -u root -ppassword -h 10.10.10.10$q$, $q$mysql -h 10.10.10.10 -u root -ppassword$q$]::text[], $q$El usuario va con -u y la contrasena con -p pegada, sin espacio, y el host con -h.$q$, $q$mysql -u root -ppassword -h 10.10.10.10 conecta al servidor. El detalle que casi todo el mundo falla es que NO hay espacio entre -p y la contrasena. Si escribes -p password, MySQL interpreta 'password' como el nombre de la base de datos y te pide la clave aparte. Con -h indicas el host remoto.$q$),
    (t_id, $q$Sospechas que el MySQL de 10.10.10.10 permite login sin contrasena y quieres comprobarlo con el script de nmap correspondiente. Escribe el comando.$q$, array[$q$nmap -sV -p3306 --script mysql-empty-password 10.10.10.10$q$, $q$nmap -p3306 --script mysql-empty-password 10.10.10.10$q$, $q$nmap --script mysql-empty-password -p3306 10.10.10.10$q$, $q$sudo nmap -sV -p3306 --script mysql-empty-password 10.10.10.10$q$]::text[], $q$El script de nmap se llama mysql-empty-password.$q$, $q$nmap -sV -p3306 --script mysql-empty-password 10.10.10.10 revisa si alguna cuenta, tipicamente root, entra sin contrasena. Es una mala configuracion comun y un camino directo de acceso, por eso conviene probarlo temprano en la enumeracion.$q$),
    (t_id, $q$Ya estas dentro de la sesion MySQL y quieres ver todas las bases de datos disponibles. Escribe el comando.$q$, array[$q$show databases;$q$, $q$SHOW DATABASES;$q$, $q$show databases$q$]::text[], $q$Es una sentencia SQL que muestra las bases de datos, terminada en punto y coma.$q$, $q$show databases; lista todas las bases de datos del servidor. Las de sistema (information_schema, mysql, performance_schema, sys) vienen por defecto, asi que lo interesante son las que no reconozcas, que suelen contener los datos de la aplicacion. No olvides el punto y coma al final.$q$),
    (t_id, $q$Viste una base de datos llamada 'users' y quieres seleccionarla para trabajar sobre ella. Escribe el comando.$q$, array[$q$use users;$q$, $q$USE users;$q$, $q$use users$q$]::text[], $q$La sentencia SQL para seleccionar una base empieza con use.$q$, $q$use users; te posiciona dentro de esa base de datos, de modo que las consultas siguientes aplican sobre ella. Es el paso previo a listar tablas y leer datos.$q$),
    (t_id, $q$Ya estas dentro de una base de datos y quieres listar todas sus tablas. Escribe el comando.$q$, array[$q$show tables;$q$, $q$SHOW TABLES;$q$, $q$show tables$q$]::text[], $q$Es la sentencia hermana de show databases, pero para tablas.$q$, $q$show tables; lista las tablas de la base seleccionada. De aqui identificas cuales pueden tener credenciales, hashes o informacion sensible, para luego leerlas con un select.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$MSSQL$q$, $q$MSSQL (1433 tcp)$q$, $q$Microsoft SQL Server. Sistema de gestion de bases de datos de Microsoft, corre por defecto en el puerto 1433. La instancia por defecto suele llamarse MSSQLSERVER y las bases de sistema son master, model, msdb y tempdb. En enumeracion buscamos version, credenciales debiles (tipico sa con clave debil o vacia), configuraciones peligrosas como xp_cmdshell, y una vez dentro exploramos bases y tablas. Cliente principal en Linux: mssqlclient.py de Impacket.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -p1433 --script ms-sql-info 10.10.10.10$q$, $q$Escaneo basico que identifica la instancia MSSQL y trae informacion de version y configuracion.$q$),
    (t_id, $q$nmap -sV -p1433 --script ms-sql-ntlm-info 10.10.10.10$q$, $q$Fuerza una respuesta NTLM del servidor que revela NetBIOS, nombre DNS y version del OS.$q$),
    (t_id, $q$nmap -sV -p1433 --script ms-sql-empty-password 10.10.10.10$q$, $q$Comprueba si alguna cuenta, tipicamente sa, permite login sin contrasena.$q$),
    (t_id, $q$impacket-mssqlclient <usuario>:<contrasena>@10.10.10.10$q$, $q$Se conecta a la instancia MSSQL con el cliente de Impacket usando autenticacion SQL.$q$),
    (t_id, $q$impacket-mssqlclient <usuario>:<contrasena>@10.10.10.10 -windows-auth$q$, $q$Se conecta usando autenticacion de Windows en vez de autenticacion SQL.$q$),
    (t_id, $q$mssqlclient.py <usuario>:<contrasena>@10.10.10.10$q$, $q$Misma conexion invocando directamente el script mssqlclient.py de Impacket.$q$),
    (t_id, $q$SELECT @@version;$q$, $q$Dentro de la sesion MSSQL, devuelve la version completa del servidor.$q$),
    (t_id, $q$SELECT name FROM sys.databases;$q$, $q$Dentro de la sesion, lista todas las bases de datos del servidor.$q$),
    (t_id, $q$enable_xp_cmdshell$q$, $q$Comando del propio mssqlclient que intenta habilitar xp_cmdshell para ejecutar comandos del sistema operativo.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres identificar la instancia MSSQL de 10.10.10.10 y traer su informacion basica con el script de nmap especifico. Escribe el comando.$q$, array[$q$nmap -sV -p1433 --script ms-sql-info 10.10.10.10$q$, $q$nmap -p1433 --script ms-sql-info 10.10.10.10$q$, $q$nmap --script ms-sql-info -p1433 10.10.10.10$q$, $q$sudo nmap -sV -p1433 --script ms-sql-info 10.10.10.10$q$]::text[], $q$El script se llama ms-sql-info y MSSQL escucha en el puerto 1433.$q$, $q$nmap -sV -p1433 --script ms-sql-info 10.10.10.10 identifica la instancia MSSQL y devuelve version, nombre de instancia y datos del servidor. Es el arranque de la enumeracion antes de intentar autenticarte.$q$),
    (t_id, $q$Encontraste las credenciales sa con contrasena 'Password1' en 10.10.10.10. Conectate a la instancia MSSQL usando el cliente de Impacket con autenticacion SQL. Escribe el comando.$q$, array[$q$impacket-mssqlclient sa:Password1@10.10.10.10$q$, $q$mssqlclient.py sa:Password1@10.10.10.10$q$, $q$python3 mssqlclient.py sa:Password1@10.10.10.10$q$]::text[], $q$El cliente es mssqlclient de Impacket y el formato de credenciales es usuario:contrasena@IP.$q$, $q$impacket-mssqlclient sa:Password1@10.10.10.10 abre una sesion contra la instancia usando autenticacion SQL. La cuenta sa es el administrador del sistema en MSSQL, asi que si entras con ella tienes control total. En Linux es el cliente estandar para MSSQL porque no dependes de herramientas de Windows.$q$),
    (t_id, $q$Las credenciales de 10.10.10.10 son de dominio y necesitas autenticacion de Windows en vez de SQL. Conectate con el cliente de Impacket usando el flag apropiado (usuario sql_svc, clave Secret123). Escribe el comando.$q$, array[$q$impacket-mssqlclient sql_svc:Secret123@10.10.10.10 -windows-auth$q$, $q$mssqlclient.py sql_svc:Secret123@10.10.10.10 -windows-auth$q$]::text[], $q$Es la misma conexion de Impacket pero agregando el flag -windows-auth al final.$q$, $q$impacket-mssqlclient sql_svc:Secret123@10.10.10.10 -windows-auth usa autenticacion de Windows en lugar de la autenticacion SQL nativa. El flag -windows-auth es necesario cuando las credenciales son de cuentas del dominio o locales de Windows y no logins propios de SQL Server.$q$),
    (t_id, $q$Ya estas dentro de la sesion MSSQL y quieres ver la version completa del servidor. Escribe la consulta.$q$, array[$q$SELECT @@version;$q$, $q$select @@version;$q$, $q$SELECT @@VERSION;$q$, $q$select @@version$q$]::text[], $q$Es un SELECT sobre la variable global de version, que lleva doble arroba.$q$, $q$SELECT @@version; devuelve la version completa de SQL Server, incluyendo edicion y sistema operativo. @@version es una variable global del servidor, por eso lleva el doble arroba. Es lo primero que se consulta al entrar para saber contra que estas.$q$),
    (t_id, $q$Dentro de la sesion quieres listar todas las bases de datos del servidor consultando la vista de sistema. Escribe la consulta.$q$, array[$q$SELECT name FROM sys.databases;$q$, $q$select name from sys.databases;$q$, $q$SELECT name FROM sys.databases$q$, $q$select name from sys.databases$q$]::text[], $q$Haz un SELECT del campo name sobre la vista sys.databases.$q$, $q$SELECT name FROM sys.databases; lista todas las bases de datos. Las de sistema (master, model, msdb, tempdb) siempre estan, asi que lo interesante son las bases personalizadas que aparezcan, que contienen los datos reales. En el examen suelen pedir justo el nombre de la base no predeterminada.$q$);
